svg.script:
const COLORS = ['#FFFFFF', '#E27474', '#95C11F'];
const leds = Array.from(document.querySelectorAll('polygon.led'));
leds.forEach(led => {
  function tick() {
    const cur = led.getAttribute('fill');
    let next;
    do { next = COLORS[Math.floor(Math.random() * COLORS.length)]; } while (next === cur);
    led.setAttribute('fill', next);
    const r = Math.random();
    const hold = Math.round(120 + Math.pow(r, 2.2) * 1800);
    setTimeout(tick, hold);
  }
  setTimeout(tick, Math.random() * 400);
});
